import{z as d,x as p,o as s,c as u,q as o,j as t,D as r,d as n,s as c,S as l,b as e}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"runc 与 containerd","description":"","frontmatter":{"title":"runc 与 containerd","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/container-runtime.md","filePath":"cs/container-runtime.md","lastUpdated":1791063341000}'),m={name:"cs/container-runtime.md"};function E(h,a,B,A,f,D){const i=p("Mermaid");return s(),u("div",null,[a[2]||(a[2]=o('<h1 id="runc-与-containerd" tabindex="-1">runc 与 containerd <a class="header-anchor" href="#runc-与-containerd" aria-label="Permalink to &quot;runc 与 containerd&quot;">​</a></h1><div class="epigraph"><p>runc 按 OCI 配置把进程放进命名空间与 cgroup；containerd 管镜像、监督、shim，真正的隔离仍是内核原语。</p><footer>—— 据 OCI Runtime Spec；containerd 文档；[namespaces](/cs/namespaces) 与 [cgroups](/cs/cgroups) 为先修</footer></div><p><a href="/cs/nested-virtualization">上一课</a>是套 VM。<a href="/cs/overlayfs">overlay</a> 已有层。缺口是 <strong>运行时</strong>：runc 如何 <code>clone</code>，containerd 如何盯着它。不是 Docker 产品史。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>OCI config.json：rootfs、ns、cap、mount。runc：创建 ns、写 cgroup、exec 用户 pid 1。containerd：拉镜像、快照、调 runc、shim 收 SIGCHLD。缺口：与 <a href="/cs/systemd-units">systemd</a> cgroup 驱动；与 <a href="/cs/netns-veth">netns veth</a>。本课不把 k8s CRI 写成编排课。</p><p><span class="marginnote">shim 让 daemon 升级不杀容器。对象是用户态拼内核隔离，不是新内核。</span></p><p><span class="marginnote">shim 就是「替 daemon 当爹」的小进程：每个容器一个，作为容器进程的直接父进程守在旁边，负责等它退出并回收 SIGCHLD。daemon 挂了它不跟着挂，容器自然不陪葬。</span></p><p><span class="marginnote">数字实例：spec 里把内存上限写成 512（MiB），runc 就在对应 cgroup 路径写下 memory.max = 536870912 字节；进程超限时由内核直接 OOM 杀掉——限额从头到尾是内核在执行，runc 只负责把数字写进去。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>unpack 层到 overlay → 生成 spec → runc start。对照 <a href="/cs/kvm-qemu">QEMU</a>：一个进 VMX，一个进 ns。对照 <a href="/cs/fuse">FUSE</a>：rootfs 通常是普通 FS。对照 LSM：可带 SELinux 标签。</p>',10)),(s(),t(l,null,{default:r(()=>[c(i,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20IMG%5B%22%E9%95%9C%E5%83%8F%E5%BF%AB%E7%85%A7%22%5D%20--%3E%20SPEC%5B%22OCI%20config%22%5D%0A%20%20SPEC%20--%3E%20RUNC%5B%22clone%20ns%20%2B%20cgroup%22%5D%0A%20%20RUNC%20--%3E%20PID1%5B%22%E5%AE%B9%E5%99%A8%E5%86%85%20init%22%5D%0A%20%20CT%5B%22containerd%22%5D%20--%3E%20RUNC%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[n("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,[n("容器运行时把已有内核隔离收成可复现的 JSON，使打包与云调度成为可能。安全等于内核+配置，不是 runc 魔法。不要写成 Docker 教程。与 "),e("a",{href:"/cs/linux-capabilities"},"capabilities"),n("：spec 里 drop。与 "),e("a",{href:"/cs/memcg"},"memcg"),n("：这里落地。")],-1)),a[5]||(a[5]=e("p",null,"逃逸往往是内核漏洞或错误特权，不是「容器不是 VM」口号能挡的。",-1)),(s(),t(l,null,{default:r(()=>[c(i,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20P1%5B%22%E5%AE%B9%E5%99%A8%E5%86%85%20pid%201%22%5D%20--%3E%20SHIM%5B%22shim%3A%20%E7%9B%B4%E6%8E%A5%E7%88%B6%E8%BF%9B%E7%A8%8B%22%5D%0A%20%20SHIM%20--%3E%20CD%5B%22containerd%22%5D%0A%20%20CD%20--%20%22%E5%8D%87%E7%BA%A7%E6%88%96%E9%87%8D%E5%90%AF%22%20--%3E%20NEW%5B%22%E6%96%B0%20containerd%20%E8%BF%9B%E7%A8%8B%22%5D%0A%20%20NEW%20--%20%22%E9%87%8D%E8%BF%9E%2C%20%E5%AE%B9%E5%99%A8%E4%B8%8D%E4%B8%AD%E6%96%AD%22%20--%3E%20SHIM%0A%20%20P1%20--%20%22%E9%80%80%E5%87%BA%22%20--%3E%20WAIT%5B%22shim%20%E6%94%B6%20SIGCHLD%20%E5%B9%B6%E4%B8%8A%E6%8A%A5%E7%8A%B6%E6%80%81%22%5D%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=o('<p>实现上：spec 里的 mounts 把 proc/sys 以安全选项挂上，漏了就会看到宿主。shim 的父进程若是 containerd，升级 daemon 不杀容器。cgroup 路径决定统计落在哪。 读法上只引用<a href="/cs/nested-virtualization">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「虚拟化与隔离进阶 / 容器与内核形态」课序里，对象是 <strong>runc 与 containerd</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入所有 runtime hook。不保证 Windows 容器。下一课镜像层格式。</p><p>版本字段会变，课序钉的是机制对象「runc 与 containerd」，不是某一主线内核的结构体名。 后课默认：runc 用 ns/cgroup 启进程。OCI 层如何叠，下一课。</p><p><span class="marginnote">常见误区：以为 runc 是一个常驻服务在「跑容器」。它其实是一次性命令：读 config.json、拼好命名空间和 cgroup、把入口进程拉起来就退出。之后盯梢的有别人——shim 与 containerd。分工是「runc 搭台，daemon 唱戏」。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>runc 应用 OCI spec；containerd 管镜像与监督。</li><li>隔离来自内核，运行时只拼装。</li><li>OCI 镜像层是下一课。</li><li>出处：OCI runtime；containerd；namespaces。</li></ul>',9))])}const S=d(m,[["render",E]]);export{C as __pageData,S as default};
